 const root=new T.Group();root.name='community-tree-decorations';root.position.set(treeLayout.x,0,treeLayout.z);scene.add(root);
 const ornaments=createTreeOrnamentMeshes(root),{meshes,frames}=ornaments,dummy=new T.Object3D(),tint=new T.Color();let draft={},records=[],signature='',kind='star',color='#e5bb6b',busy=false,lastAdded='',opened=false,selected='',focused='',focusUntil=0;let recoloring=Promise.resolve();let initialized=false;const flying=new Set();let visibleRecords=[];
 const glow=new T.Mesh(new T.TorusGeometry(.74,.025,8,48),new T.MeshBasicMaterial({color:'#ffe5ac',transparent:true,opacity:0,depthWrite:false,toneMapped:false}));glow.visible=false;root.add(glow);
 const tray=document.createElement('div');tray.id='tree-tools';tray.hidden=true;tray.setAttribute('role','group');tray.setAttribute('aria-label','트리 꾸미기');
 tray.innerHTML='<div class="tree-tools-head"><strong>트리 꾸미기</strong><button data-close aria-label="트리 꾸미기 닫기"><svg viewBox="0 0 24 24"><path d="m7 7 10 10M17 7 7 17"/></svg></button></div><div class="tree-palette tree-kinds"></div><div class="tree-colors"><div class="tree-swatches"></div><label class="tree-custom-color"><span>＋</span><input type="color" aria-label="장식 사용자 지정 색상"></label></div><div class="tree-footer"><button data-add>장식 달기</button><button data-new hidden>새 장식</button><button data-wish>소원</button><button data-list>소원 목록</button><button data-undo aria-label="마지막 장식 취소" disabled><svg viewBox="0 0 24 24"><path d="M4 5v6h6M4.5 10a8 8 0 1 1 .5 7"/></svg></button></div><p role="status">트리를 눌러 달기</p>';
 for(const [id,item]of Object.entries(decorationCatalog)){const b=document.createElement('button');b.dataset.kind=id;b.setAttribute('aria-label',item.name+' 장식');b.innerHTML=decorationIcon(id)+'<span>'+item.name+'</span>';tray.querySelector('.tree-kinds').append(b);}
